#pragma once

#include <Arduino.h>
#include <WiFi.h>
#include <esp_heap_caps.h>
#include <sys/time.h>
#include <FlovaSDK.h>

using TestClient = FlovaEsp32;

namespace board_test {
inline void sampleMemory() {}
inline void printMemoryFields() {}
inline void connect() { WiFi.begin(TEST_WIFI_SSID, TEST_WIFI_PASSWORD); }
inline void begin() {
  WiFi.persistent(false);
  WiFi.setAutoReconnect(false);
  connect();
  // The private test CA was just generated by the host. Do not weaken TLS
  // validation or claim SNTP acceptance from this development-only clock.
  timeval now = {TEST_EPOCH, 0};
  settimeofday(&now, nullptr);
}
inline bool wifi() { return WiFi.status() == WL_CONNECTED; }
inline void disconnect() { WiFi.disconnect(false); }
inline void restart() { ESP.restart(); }
inline uint32_t freeHeap() { return ESP.getFreeHeap(); }
inline uint32_t minimumHeap() { return ESP.getMinFreeHeap(); }
inline uint32_t largestBlock() {
  return heap_caps_get_largest_free_block(MALLOC_CAP_8BIT);
}
inline uint32_t stackHeadroom() { return uxTaskGetStackHighWaterMark(nullptr); }
}  // namespace board_test
